<script>
// JS: показать/скрыть панель при наведении на Чуйскую область
// Всплывающая панель для карты
document.addEventListener('DOMContentLoaded', function() {
    // id области и информация
    const regions = {
        'KGB': {
            title: 'Баткенская область',
            address: 'г. Баткен, ул. Кызыл-Кия',
            crops: 'Хлопок',
            extra: 'Дополнительная информация: ...',
            highlight: '#216c3d'
        },
        'KGGB': {
            title: 'г. Бишкек',
            address: 'г. Бишкек',
            crops: '—',
            extra: '...',
            highlight: '#216c3d'
        },
        'KGC': {
            title: 'Чуйская область',
            address: 'г. Бишкек, ул. Примерная, 1',
            crops: 'Сахарная свекла, зерновые, овощи и др.',
            extra: 'Дополнительная информация: ...',
            highlight: '#216c3d'
        },
        'KGY': {
            title: 'Иссык-Кульская область',
            address: 'г. Каракол',
            crops: 'Овощи, зерновые',
            extra: 'Курортная зона',
            highlight: '#216c3d'
        },
        'KGJ': {
            title: 'Джалал-Абадская область',
            address: 'с. Тогуз-Торо',
            crops: 'Овощные культуры',
            extra: '...',
            highlight: '#216c3d'
        },
        'KGN': {
            title: 'Нарынская область',
            address: 'ул. Ленина, 209',
            crops: 'Семеноводство',
            extra: '...',
            highlight: '#216c3d'
        },
        'KGO': {
            title: 'Ошская область',
            address: 'с. Кара-Суу, ул. Большевик',
            crops: 'Зерновые культуры',
            extra: '...',
            highlight: '#216c3d'
        },
        'KGGO': {
            title: 'г. Ош',
            address: 'г. Ош',
            crops: '—',
            extra: 'Южная столица',
            highlight: '#216c3d'
        },
        'KGT': {
            title: 'Таласская область',
            address: 'г. Талас',
            crops: '...',
            extra: '...',
            highlight: '#216c3d'
        }
    };

    // Создаём панель
    let panel = document.createElement('div');
    panel.className = 'chu-info-panel';
    panel.style.display = 'none';
    document.body.appendChild(panel);

    Object.keys(regions).forEach(function(regionId) {
        const region = document.getElementById(regionId);
        if (region) {
            region.style.cursor = 'pointer';
            let originalFill = region.getAttribute('fill');
            region.addEventListener('mouseenter', function(e) {
                const info = regions[regionId];
                panel.innerHTML = `
                    <h3>${info.title}</h3>
                    <p>По этому адресу находится: <strong>${info.address}</strong></p>
                    <p>Основные культуры: ${info.crops}</p>
                    <p>${info.extra}</p>
                `;
                panel.style.display = 'block';
                // позиционируем панель справа от области
                const rect = region.getBoundingClientRect();
                panel.style.top = (window.scrollY + rect.top + rect.height/2 - panel.offsetHeight/2) + 'px';
                panel.style.left = (window.scrollX + rect.right + 18) + 'px';
                // Подсветка области
                originalFill = region.getAttribute('fill') || '#bdbdbd';
                region.setAttribute('fill', info.highlight || '#216c3d');
            });
            region.addEventListener('mouseleave', function() {
                panel.style.display = 'none';
                // Возврат цвета
                region.setAttribute('fill', originalFill);
            });
        }
    });
});
</script>
